// BookCard.jsx
import { useState } from "react";
import { Link } from "react-router-dom";
import styled, { keyframes } from "styled-components";
import Mosaic from "./Mosaic";
import withImageLoading from "../components/hoc/withImageLoading";

// --- Animations ---
const floatParticle = keyframes`
  0% { transform: translateY(0) rotate(0deg); opacity: 0.2; }
  50% { opacity: 0.6; }
  100% { transform: translateY(-100px) rotate(360deg); opacity: 0; }
`;

// --- Styled Components ---
const CardWrapper = styled.div`
  width: 100%;
  aspect-ratio: 2 / 3;
  position: relative;
  perspective: 1000px;
`;

const CardLink = styled(Link)`
  text-decoration: none;
  width: 100%;
  height: 100%;
  display: block;
`;

const Card = styled.div`
  position: relative;
  width: 100%;
  height: 100%;
  border-radius: 16px;
  overflow: hidden;
  cursor: pointer;
  transform: scale(1);
  transition: transform 0.35s ease, box-shadow 0.35s ease;
  box-shadow: 0 12px 28px rgba(0, 0, 0, 0.25);

  &:hover {
    transform: scale(1.08);
    z-index: 10;
    box-shadow: 0 25px 55px rgba(0, 0, 0, 0.45);
  }

  &:hover .overlay {
    opacity: 1;
    transform: translateY(0);
  }

  &:hover img {
    transform: scale(1.06) rotate(0.5deg);
  }
`;

// particle for glimmer effect
const Particle = styled.div`
  position: absolute;
  width: ${({ size }) => size}px;
  height: ${({ size }) => size}px;
  background: ${({ color }) => color};
  border-radius: 50%;
  top: ${({ top }) => top}%;
  left: ${({ left }) => left}%;
  opacity: 0.3;
  filter: blur(2px);
  animation: ${floatParticle} ${({ duration }) => duration}s linear infinite;
  animation-delay: ${({ delay }) => delay}s;
  z-index: 1;
`;

// Mouse-follow glimmer
const Glisten = styled.div`
  position: absolute;
  width: 120px;
  height: 120px;
  background: radial-gradient(circle, rgba(255,255,255,0.3) 0%, rgba(255,255,255,0) 70%);
  border-radius: 50%;
  pointer-events: none;
  transform: translate(-50%, -50%);
  transition: opacity 0.2s ease;
  opacity: ${({ active }) => (active ? 1 : 0)};
  z-index: 5;
`;

const BookImage = styled.img`
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.35s ease;
`;

const SpinnerWrapper = styled.div`
  position: absolute;
  inset: 0;
  display: flex;
  justify-content: center;
  align-items: center;
`;

const Overlay = styled.div`
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: 16px;

  background: linear-gradient(
    to top,
    rgba(0, 0, 0, 0.85),
    rgba(0, 0, 0, 0.5),
    rgba(0, 0, 0, 0.2),
    transparent
  );

  opacity: 0;
  transform: translateY(10px);
  transition: opacity 0.3s ease, transform 0.3s ease;
  z-index: 3;
`;

const Title = styled.h5`
  margin: 0;
  color: #fff;
  font-size: 1rem;
  font-weight: 600;
  line-height: 1.2;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
`;

const Author = styled.p`
  margin: 4px 0 0;
  color: #ccc;
  font-size: 0.85rem;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
`;

const ButtonWrapper = styled.div`
  margin-top: 8px;
  display: flex;
  justify-content: center;
`;

const BookImageWithLoading = withImageLoading(BookImage);

const particleColors = ["#ff416c", "#ff4b2b", "#ffe259", "#00c6ff", "#0072ff"];

const BookCard = ({ isbn, thumbnail, title, author }) => {
  const [glistenPos, setGlistenPos] = useState({ x: 0, y: 0, active: false });

  // generate a few floating particles for the card
  const particles = Array.from({ length: 5 }, () => ({
    size: Math.random() * 6 + 3,
    top: Math.random() * 100,
    left: Math.random() * 100,
    color: particleColors[Math.floor(Math.random() * particleColors.length)],
    duration: Math.random() * 10 + 6,
    delay: Math.random() * 4,
  }));

  const handleMouseMove = (e) => {
    const rect = e.currentTarget.getBoundingClientRect();
    setGlistenPos({
      x: e.clientX - rect.left,
      y: e.clientY - rect.top,
      active: true,
    });
  };

  const handleMouseLeave = () => {
    setGlistenPos((p) => ({ ...p, active: false }));
  };

  return (
    <CardWrapper>
      <CardLink to={`/book/${isbn}`}>
        <Card onMouseMove={handleMouseMove} onMouseLeave={handleMouseLeave}>
          {particles.map((p, i) => (
            <Particle key={i} {...p} />
          ))}
          <Glisten
            style={{ left: `${glistenPos.x}px`, top: `${glistenPos.y}px` }}
            active={glistenPos.active}
          />
          <Mosaic thumbnail={thumbnail} blur={14} tileSize={140} opacity={0.35}>
            <BookImageWithLoading src={thumbnail} alt={title} />
            <Overlay className="overlay">
              <Title title={title}>{title}</Title>
              <Author title={author}>{author}</Author>
            </Overlay>
          </Mosaic>
        </Card>
      </CardLink>
    </CardWrapper>
  );
};

export default BookCard;
